(()=>{
const checked='9 Sep 2026';
const profiles={
 'Botswana':{code:'BW',status:'Expanded field profile',gateways:['Maun','Kasane','Gaborone'],landscapes:['Okavango wetlands','Chobe–Linyanti river systems','Kalahari grasslands and salt pans'],season:'May to October is broadly drier and cooler; wildlife often gathers around permanent water. November to April generally brings heat, rain, migrant birds and greener landscapes. Okavango flood timing is distinct from local rainfall and varies by year.',regions:[['Okavango & Moremi','Permanent channels, seasonal floodplains, islands and woodland across the Delta and Moremi landscape.'],['Chobe, Savuti & Linyanti','River frontage, dry woodland and major wildlife corridors in northern Botswana.'],['Makgadikgadi & Nxai Pan','Salt-pan horizons, grasslands, seasonal water and desert-adapted wildlife.'],['Central Kalahari & Khutse','Remote semi-arid landscapes, fossil valleys and wide seasonal grasslands.'],['Northern Tuli','Limpopo and Shashe river country, rocky kopjes and private or community conservation areas.'],['Tsodilo & the Panhandle','Rock-art heritage and the upper Okavango’s deeper channels and riparian habitats.']],sources:[['Botswana Tourism Organisation','https://www.botswanatourism.co.bw/explore'],['Ministry of Environment and Tourism','https://www.gov.bw/ministries/ministry-environment-and-tourism']]},
 'South Africa':{code:'ZA',status:'Expanded field profile',gateways:['Johannesburg','Cape Town','Durban','Mbombela and Hoedspruit'],landscapes:['Lowveld savanna','Kalahari and Karoo','Cape mountains, fynbos and coast'],season:'Safari conditions vary greatly by biome. The northeast is usually drier in the austral winter and wetter in summer; the southwestern Cape follows a different winter-rainfall pattern. Check the specific park before travel.',regions:[['Kruger & the Lowveld','Large connected savanna landscapes, river systems and public and private reserves.'],['Kgalagadi','Arid Kalahari dunes, dry riverbeds and desert-adapted wildlife.'],['Mapungubwe','Limpopo–Shashe landscapes combining biodiversity, archaeology and cultural heritage.'],['Addo & the Eastern Cape','Thicket, open country and conservation areas spanning inland habitats toward the coast.'],['KwaZulu-Natal reserves & wetlands','Savanna, estuaries, coastal forest and marine environments.'],['Cape, Karoo & Garden Route','Fynbos, mountains, semi-desert, forests and coast rather than one conventional safari biome.']],sources:[['South African National Parks','https://www.sanparks.org/'],['South African Tourism','https://www.southafrica.net/']]},
 'Namibia':{code:'NA',status:'Expanded field profile',gateways:['Windhoek','Walvis Bay'],landscapes:['Etosha salt-pan system','Namib Desert and Atlantic coast','Escarpment, rugged northwest and Zambezi wetlands'],season:'The cooler dry period commonly falls from May to October, while the main rains generally occur during the hotter summer. Wildlife, road and water conditions differ sharply between desert, plateau and the Zambezi region.',regions:[['Etosha','A vast pan system with surrounding waterholes, woodland and grassland.'],['Namib-Naukluft & Sossusvlei','Ancient desert, high dunes, gravel plains and mountain canyons.'],['Skeleton Coast','Fog-influenced Atlantic desert, dune fields and highly remote coast.'],['Kunene & the northwest','Rugged escarpment and desert valleys supporting dispersed, mobile wildlife.'],['Zambezi conservation landscape','Rivers, floodplains and woodlands connecting wider transboundary ecosystems.'],['Waterberg & the south','Sandstone plateau habitat plus southern desert, canyon and succulent landscapes.']],sources:[['Namibia Wildlife Resorts parks','https://www.nwr.com.na/national-parks/'],['Ministry of Environment, Forestry and Tourism','https://www.meft.gov.na/']]},
 'Zimbabwe':{code:'ZW',status:'Expanded field profile',gateways:['Harare','Victoria Falls','Bulawayo'],landscapes:['Zambezi valley and floodplain','Mopane and teak woodland','Granite hills and eastern mountains'],season:'The cooler dry season commonly runs from about May to October and the warmer rains from roughly November to April. Heat, water levels and access can vary considerably by park and year.',regions:[['Hwange','Extensive woodland and grassland with natural and managed water sources.'],['Mana Pools & the middle Zambezi','River terraces, floodplain, woodland and escarpment wilderness.'],['Gonarezhou','Large lowveld landscape of rivers, sandstone cliffs and mopane woodland.'],['Matobo','Granite kopjes, cultural landscapes and important wildlife areas.'],['Victoria Falls & Zambezi parks','Riverine habitats around a globally significant waterfall landscape.'],['Eastern Highlands','Montane scenery, forest, grassland and high-rainfall biodiversity.']],sources:[['Zimbabwe Parks and Wildlife Management Authority','https://www.zimparks.org.zw/'],['Zimbabwe Tourism Authority','https://zimbabwetourism.net/']]},
 'Zambia':{code:'ZM',status:'Expanded field profile',gateways:['Lusaka','Livingstone','Mfuwe'],landscapes:['Luangwa Valley','Kafue basin and floodplains','Zambezi river systems and Bangweulu wetlands'],season:'The broad dry season usually falls from May to October and the rains from November to April. Access, camp operations, river levels and wildlife movement are strongly local and must be checked for the intended area.',regions:[['South & North Luangwa','River, lagoon, floodplain and woodland ecosystems along the Luangwa Valley.'],['Lower Zambezi','Escarpment-to-river habitat facing a wider transboundary conservation landscape.'],['Kafue','A very large and varied system including woodland, rivers and seasonal floodplains.'],['Liuwa Plain','Open grassland and seasonal wetlands in western Zambia.'],['Bangweulu','A major wetland and floodplain landscape with distinctive water-dependent wildlife.'],['Mosi-oa-Tunya & the upper Zambezi','Riverine wildlife and the Zambian side of the Victoria Falls landscape.']],sources:[['Department of National Parks and Wildlife','https://www.mot.gov.zm/dnpw/'],['Zambia Tourism','https://www.zambiatourism.com/']]}
};
const esc=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function fallback(country,atlasRow){const highlights=String(atlasRow?.[2]||'').split(/,|·|—/).map(x=>x.trim()).filter(Boolean).slice(0,6);return {code:'',status:'Core country profile',gateways:[],landscapes:[],regions:highlights.map((name,index)=>[name,index?'Curated place in the Pocketbook destination index. Verify current access and conditions locally.':'A starting point for exploring this country’s nature and cultural landscapes.']),sources:[]}}
window.countryDepthHtml=(country,atlasRow)=>{const p=profiles[country]||fallback(country,atlasRow),expanded=Boolean(profiles[country]);return `<section class="entry-section country-depth" data-depth-country="${esc(country)}" data-depth-code="${esc(p.code)}"><div class="depth-heading"><div><div class="entry-kicker">FIELD PROFILE</div><h3>${expanded?'Safari regions at a glance':'Build your country field picture'}</h3></div><span class="profile-status ${expanded?'expanded':''}">${esc(p.status)}</span></div><nav class="country-shortcuts" aria-label="${esc(country)} pocketbook tools">${p.code?`<button type="button" data-country-wildlife="${esc(p.code)}">Wildlife</button>`:''}<button type="button" data-country-map="${esc(country)}">Map</button><button type="button" data-country-language>Languages</button><button type="button" data-country-safety="${esc(country)}">Safety</button></nav>${p.gateways.length?`<div class="depth-group"><strong>Common journey gateways</strong><p>${p.gateways.map(esc).join(' · ')}</p></div>`:''}${p.landscapes.length?`<div class="depth-group"><strong>Landscape compass</strong><div class="landscape-chips">${p.landscapes.map(x=>`<span>${esc(x)}</span>`).join('')}</div></div>`:''}<div class="region-list">${p.regions.length?p.regions.map(([name,note])=>`<article><h4>${esc(name)}</h4><p>${esc(note)}</p></article>`).join(''):`<div class="depth-empty"><strong>Regional field notes are being expanded.</strong><p>Use the live map, country wildlife browser and official sources while this editorial entry grows.</p></div>`}</div>${p.season?`<div class="season-note"><strong>Seasonal pattern—not a forecast</strong><p>${esc(p.season)}</p><small>Conditions vary by year and location. Confirm roads, weather, water, access and opening status before setting out.</small></div>`:''}<div class="depth-sources"><strong>Official starting points</strong>${p.sources.length?p.sources.map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener">${esc(name)} ↗</a>`).join(''):'<p>Official tourism and protected-area sources are being added to this entry.</p>'}<small>Bundled editorial profile reviewed ${checked}. It is not live operational advice.</small></div></section>`};
window.mountCountryDepth=(country)=>{const root=[...document.querySelectorAll('.country-depth')].find(node=>node.dataset.depthCountry===country);if(!root)return;root.querySelector('[data-country-language]')?.addEventListener('click',()=>root.nextElementSibling?.scrollIntoView({behavior:'smooth',block:'start'}));root.querySelector('[data-country-wildlife]')?.addEventListener('click',event=>{const code=event.currentTarget.dataset.countryWildlife;if(!code)return;document.querySelector('.country-close')?.click();window.openPocketbookView?.('field');document.querySelector('#faunaMode [data-mode="database"]')?.click();const select=document.getElementById('faunaCountry');if(select){select.value=code;select.dispatchEvent(new Event('change',{bubbles:true}))}});root.querySelector('[data-country-map]')?.addEventListener('click',event=>{document.querySelector('.country-close')?.click();window.openPocketbookView?.('map');const input=document.getElementById('mapSearch');if(input){input.value=event.currentTarget.dataset.countryMap;input.dispatchEvent(new Event('input',{bubbles:true}));input.focus()}});root.querySelector('[data-country-safety]')?.addEventListener('click',event=>{document.querySelector('.country-close')?.click();document.getElementById('sosButton')?.click();const select=document.getElementById('safetyCountry');if(select){select.value=event.currentTarget.dataset.countrySafety;select.dispatchEvent(new Event('change',{bubbles:true}))}})};
})();
